import json
from itertools import product

def solve():
    houses = [None] + [dict(Name=None, **{"hair colors": None, "heights": None}) for _ in range(6)]
    names = ["Bob", "Peter", "Eric", "Alice", "Arnold", "Carol"]
    hair_colors = ["auburn", "blonde", "brown", "black", "red", "gray"]
    heights = ["very tall", "average", "very short", "tall", "super tall", "short"]

    used_names = set()
    used_hairs = set()
    used_heights = set()

    # Pre-assign fixed clues
    # 2. Alice is in the fourth house.
    houses[4]["Name"] = "Alice"; used_names.add("Alice")
    # 12. The person who has gray hair is in the third house.
    houses[3]["hair colors"] = "gray"; used_hairs.add("gray")
    # 10. The person who is very short is in the fifth house.
    houses[5]["heights"] = "very short"; used_heights.add("very short")
    # 4. The person who is tall is in the sixth house.
    houses[6]["heights"] = "tall"; used_heights.add("tall")

    def pos_of_name(nm):
        for i in range(1,7):
            if houses[i]["Name"] == nm:
                return i
        return None

    def pos_of_hair(hr):
        for i in range(1,7):
            if houses[i]["hair colors"] == hr:
                return i
        return None

    def pos_of_height(ht):
        for i in range(1,7):
            if houses[i]["heights"] == ht:
                return i
        return None

    def check_equalities_local(i):
        n = houses[i]["Name"]
        h = houses[i]["hair colors"]
        ht = houses[i]["heights"]

        # 11. Bob is the person who has brown hair.
        if n == "Bob" and h is not None and h != "brown":
            return False
        if h == "brown" and n is not None and n != "Bob":
            return False

        # 6. The person who has red hair is Eric.
        if n == "Eric" and h is not None and h != "red":
            return False
        if h == "red" and n is not None and n != "Eric":
            return False

        # 8. The person who has blonde hair is Carol.
        if n == "Carol" and h is not None and h != "blonde":
            return False
        if h == "blonde" and n is not None and n != "Carol":
            return False

        # 13. The person who has blonde hair is the person who is very tall.
        if h == "blonde" and ht is not None and ht != "very tall":
            return False
        if ht == "very tall" and h is not None and h != "blonde":
            return False

        # 3. The person who is short is Arnold.
        if n == "Arnold" and ht is not None and ht != "short":
            return False
        if ht == "short" and n is not None and n != "Arnold":
            return False

        # 5. The person who has black hair is not in the fourth house.
        if i == 4 and h == "black":
            return False

        # 2. Alice is in the fourth house.
        if i == 4 and n is not None and n != "Alice":
            return False
        if i != 4 and n == "Alice":
            return False

        # 12. Gray hair in the third house.
        if i == 3 and h is not None and h != "gray":
            return False
        if i != 3 and h == "gray":
            return False

        # 10. Very short in the fifth house.
        if i == 5 and ht is not None and ht != "very short":
            return False
        if i != 5 and ht == "very short":
            return False

        # 4. Tall in the sixth house.
        if i == 6 and ht is not None and ht != "tall":
            return False
        if i != 6 and ht == "tall":
            return False

        return True

    def check_global_constraints_partial():
        # 1. Blonde is directly left of Bob.
        p_blonde = pos_of_hair("blonde")
        p_bob = pos_of_name("Bob")
        if p_blonde is not None and p_bob is not None:
            if p_bob != p_blonde + 1:
                return False
        if p_blonde is not None:
            if p_blonde == 6:
                return False
            # enforce neighbor consistency
            nb = p_blonde + 1
            if houses[nb]["Name"] is not None and houses[nb]["Name"] != "Bob":
                return False
            if p_bob is not None and p_bob != nb:
                return False
        if p_bob is not None:
            if p_bob == 1:
                return False
            lb = p_bob - 1
            if houses[lb]["hair colors"] is not None and houses[lb]["hair colors"] != "blonde":
                return False
            if p_blonde is not None and p_blonde != lb:
                return False

        # 6. Red hair is Eric (already local). No global needed.

        # 9. One house between gray and red.
        p_gray = pos_of_hair("gray")
        p_red = pos_of_hair("red")
        # gray fixed at 3, but keep generic
        if p_gray is not None and p_red is not None:
            if abs(p_gray - p_red) != 2:
                return False
        elif p_gray is not None:
            candidates = []
            for c in (p_gray - 2, p_gray + 2):
                if 1 <= c <= 6:
                    ok = True
                    # hair slot viability
                    hc = houses[c]["hair colors"]
                    if hc is not None and hc != "red":
                        ok = False
                    # name must be Eric if red
                    nm = houses[c]["Name"]
                    if ok and nm is not None and nm != "Eric":
                        ok = False
                    candidates.append(ok)
            if not candidates or not any(candidates):
                return False
        elif p_red is not None:
            candidates = []
            for c in (p_red - 2, p_red + 2):
                if 1 <= c <= 6:
                    ok = True
                    hc = houses[c]["hair colors"]
                    if hc is not None and hc != "gray":
                        ok = False
                    # also ensure gray uniqueness with preassign means c must be 3; this will be enforced
                    candidates.append(ok)
            if not candidates or not any(candidates):
                return False

        # 7. Super tall to the right of average.
        p_super = pos_of_height("super tall")
        p_avg = pos_of_height("average")
        if p_super is not None and p_avg is not None:
            if not (p_super > p_avg):
                return False
        elif p_super is not None:
            # Need some slot to the left for average
            possible = False
            for j in range(1, p_super):
                ht = houses[j]["heights"]
                if ht is None or ht == "average":
                    possible = True
                    break
            if not possible:
                return False
        elif p_avg is not None:
            # Need some slot to the right for super tall
            possible = False
            for j in range(p_avg + 1, 7):
                ht = houses[j]["heights"]
                if ht is None or ht == "super tall":
                    possible = True
                    break
            if not possible:
                return False

        # Check local equalities consistency for all houses
        for i in range(1,7):
            if not check_equalities_local(i):
                return False

        return True

    # Generate candidate triples for a given house index
    def candidates_for_house(i):
        cell = houses[i]
        if cell["Name"] is not None and cell["hair colors"] is not None and cell["heights"] is not None:
            return [ (cell["Name"], cell["hair colors"], cell["heights"]) ]

        # name options
        if cell["Name"] is not None:
            name_opts = [cell["Name"]]
        else:
            name_opts = [n for n in names if n not in used_names]
            # Clue 2: Alice must be in house 4
            if i == 4:
                name_opts = ["Alice"] if "Alice" not in used_names or houses[4]["Name"] == "Alice" else []
            else:
                name_opts = [n for n in name_opts if n != "Alice"]

        # hair options
        if cell["hair colors"] is not None:
            hair_opts = [cell["hair colors"]]
        else:
            hair_opts = [c for c in hair_colors if c not in used_hairs]
            if i == 4 and "black" in hair_opts:
                hair_opts.remove("black")
            # Clue 12: gray at 3
            if i == 3:
                hair_opts = ["gray"] if "gray" not in used_hairs or houses[3]["hair colors"] == "gray" else []
            else:
                hair_opts = [c for c in hair_opts if c != "gray"]

        # height options
        if cell["heights"] is not None:
            height_opts = [cell["heights"]]
        else:
            height_opts = [h for h in heights if h not in used_heights]
            # Clue 10: very short at 5
            if i == 5:
                height_opts = ["very short"] if "very short" not in used_heights or houses[5]["heights"] == "very short" else []
            else:
                height_opts = [h for h in height_opts if h != "very short"]
            # Clue 4: tall at 6
            if i == 6:
                height_opts = ["tall"] if "tall" not in used_heights or houses[6]["heights"] == "tall" else []
            else:
                height_opts = [h for h in height_opts if h != "tall"]

        cands = []
        for n, c, h in product(name_opts, hair_opts, height_opts):
            # Apply equality constraints inline to prune
            # Bob <-> brown
            if (n == "Bob" and c != "brown") or (c == "brown" and n != "Bob"):
                continue
            # Eric <-> red
            if (n == "Eric" and c != "red") or (c == "red" and n != "Eric"):
                continue
            # Carol <-> blonde
            if (n == "Carol" and c != "blonde") or (c == "blonde" and n != "Carol"):
                continue
            # blonde <-> very tall
            if (c == "blonde" and h != "very tall") or (h == "very tall" and c != "blonde"):
                continue
            # Arnold <-> short
            if (n == "Arnold" and h != "short") or (h == "short" and n != "Arnold"):
                continue
            # Clue 1: blonde directly left of Bob - local feasibility
            if c == "blonde":
                if i == 6:
                    continue
                # If right neighbor assigned name and not Bob -> impossible
                rn = houses[i+1]["Name"]
                if rn is not None and rn != "Bob":
                    continue
                # If Bob already assigned elsewhere and not i+1 -> impossible
                p_bob = pos_of_name("Bob")
                if p_bob is not None and p_bob != i+1:
                    continue
            if n == "Bob":
                if i == 1:
                    continue
                # If left neighbor hair assigned and not blonde -> impossible
                lh = houses[i-1]["hair colors"]
                if lh is not None and lh != "blonde":
                    continue
                # If blonde already assigned elsewhere and not i-1 -> impossible
                p_bl = pos_of_hair("blonde")
                if p_bl is not None and p_bl != i-1:
                    continue
            # Clue 9: distance between gray and red
            if c == "red":
                pg = pos_of_hair("gray")  # likely 3
                if pg is not None and abs(pg - i) != 2:
                    continue
            # Clue 7: super tall to right of average - local feasibility
            if h == "super tall":
                p_avg = pos_of_height("average")
                if p_avg is not None and not (i > p_avg):
                    continue
                if p_avg is None:
                    # ensure some slot left can be average
                    found = False
                    for j in range(1, i):
                        hj = houses[j]["heights"]
                        if hj is None or hj == "average":
                            found = True
                            break
                    if not found:
                        continue
            if h == "average":
                p_super = pos_of_height("super tall")
                if p_super is not None and not (p_super > i):
                    continue
                if p_super is None:
                    found = False
                    for j in range(i+1, 7):
                        hj = houses[j]["heights"]
                        if hj is None or hj == "super tall":
                            found = True
                            break
                    if not found:
                        continue
            # Other local checks
            prev_name = houses[i]["Name"]
            prev_hair = houses[i]["hair colors"]
            prev_height = houses[i]["heights"]
            # if preassigned values exist, ensure they match
            if prev_name is not None and prev_name != n:
                continue
            if prev_hair is not None and prev_hair != c:
                continue
            if prev_height is not None and prev_height != h:
                continue
            cands.append((n, c, h))
        return cands

    def all_assigned():
        for i in range(1,7):
            if houses[i]["Name"] is None or houses[i]["hair colors"] is None or houses[i]["heights"] is None:
                return False
        return True

    def select_house():
        # choose house with minimum number of candidates
        best_i = None
        best_len = None
        best_cands = None
        for i in range(1,7):
            if houses[i]["Name"] is not None and houses[i]["hair colors"] is not None and houses[i]["heights"] is not None:
                continue
            cands = candidates_for_house(i)
            l = len(cands)
            if l == 0:
                return i, []
            if best_len is None or l < best_len:
                best_len = l
                best_i = i
                best_cands = cands
        return best_i, best_cands

    def assign(i, triple):
        n, c, h = triple
        # Track which fields are newly assigned to update used sets properly
        prev = (houses[i]["Name"], houses[i]["hair colors"], houses[i]["heights"])
        if houses[i]["Name"] is None:
            used_names.add(n)
        else:
            # if changing (shouldn't happen), adjust sets
            if houses[i]["Name"] != n:
                used_names.discard(houses[i]["Name"])
                used_names.add(n)
        houses[i]["Name"] = n

        if houses[i]["hair colors"] is None:
            used_hairs.add(c)
        else:
            if houses[i]["hair colors"] != c:
                used_hairs.discard(houses[i]["hair colors"])
                used_hairs.add(c)
        houses[i]["hair colors"] = c

        if houses[i]["heights"] is None:
            used_heights.add(h)
        else:
            if houses[i]["heights"] != h:
                used_heights.discard(houses[i]["heights"])
                used_heights.add(h)
        houses[i]["heights"] = h
        return prev

    def unassign(i, prev):
        pn, pc, ph = prev
        cn, cc, ch = houses[i]["Name"], houses[i]["hair colors"], houses[i]["heights"]
        # Remove current from used sets
        if cn is not None:
            used_names.discard(cn)
        if cc is not None:
            used_hairs.discard(cc)
        if ch is not None:
            used_heights.discard(ch)
        # Restore previous values and sets
        houses[i]["Name"] = pn
        houses[i]["hair colors"] = pc
        houses[i]["heights"] = ph
        if pn is not None:
            used_names.add(pn)
        if pc is not None:
            used_hairs.add(pc)
        if ph is not None:
            used_heights.add(ph)

    def search():
        if not check_global_constraints_partial():
            return False
        if all_assigned():
            return True
        i, cands = select_house()
        if cands is None or len(cands) == 0:
            return False
        for triple in cands:
            prev = assign(i, triple)
            if check_global_constraints_partial():
                if search():
                    return True
            unassign(i, prev)
        return False

    success = search()
    if not success:
        raise RuntimeError("No solution found")

    # Build output
    header = ["House", "Name", "hair colors", "heights"]
    rows = []
    for i in range(1,7):
        rows.append([str(i), houses[i]["Name"], houses[i]["hair colors"], houses[i]["heights"]])
    return {"solution": {"header": header, "rows": rows}}

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
